  private obtenerCuenta(productoFinanciero: string) {
    this.refrescarCuentas()
    this.calcularParecidos(productoFinanciero)
    this.ordenarCuentas()
    return this.cuentasFideicomiso[0]
  }

  private refrescarCuentas() {
    this.cuentasFideicomiso.forEach((cuenta) => cuenta.parecido = 0)
  }

  private calcularParecidos(value: string) {
    this.cuentasFideicomiso.forEach((cuenta) => {
      cuenta.parecido = this.utils2.calcularPuntuacionSimilitud(value, cuenta.programa)
    })
  }

  private ordenarCuentas() {
    this.cuentasFideicomiso.sort((a, b) => b.parecido - a.parecido)
  }

  formatDecimals(value: number | undefined | null): string {
    const num = Number(value);

    if (isNaN(num)) return '00/100 MN';

    const decimalPart = Math.round((num % 1) * 100);
    const padded = decimalPart.toString().padStart(2, '0');

    return `${padded}/100 MN`;
  }

  formatearNumeroConComas(valor?: number | string): string {
    const numero = Number(valor);
    if (isNaN(numero)) return String(valor);

    // Ensure two decimal places
    const [entero, decimales] = numero.toFixed(2).split('.');

    // Add commas to the integer part
    const enteroConComas = entero.replace(/\B(?=(\d{3})+(?!\d))/g, ',');

    return `${enteroConComas}.${decimales}`;
  }

  private async generateAndDownloadMultiplePDFs(creditos:Credito[], pdfDefinitions: any[]) {
    const zip = new JSZip();

    for (let i = 0; i < pdfDefinitions.length; i++) {
        const pdf = pdfMake.createPdf(pdfDefinitions[i]);
        const pdfBlob = await this.getPdfBlob(pdfDefinitions[i]); // Esperamos el Blob
        zip.file(`carta_instruccion_FBC-${creditos[i].id}.pdf`, pdfBlob);
    }

    const zipBlob = await zip.generateAsync({ type: 'blob' });
    saveAs(zipBlob, 'cartas.zip');
  }

  private getPdfBlob(pdfDef : any): Promise<Blob> {
    return new Promise((resolve) => {
        pdfMake.createPdf(pdfDef).getBlob(result => resolve(result));
    });
  }

  public async multiplesMachoteCartasInstrucciones(creditos: Credito[], showFirma:boolean=false){
    const docDefinitions:any[]=[]
    for(const credito of creditos) {
      docDefinitions.push( await this.generateDocDefinitionPdfMake(credito, showFirma) )
    }
    await this.generateAndDownloadMultiplePDFs(creditos, docDefinitions)
  }

  public async machoteCartaInstrucciones(creditoParam?: Credito, showFirma:boolean=false) {
    if (!creditoParam) return
    const credito = await this.creditoController.find(creditoParam.id, [
      'datosPersonales',
      'sesiones',
      'datosPersonales.ciudades',
      'productosFinancieros',
      "inversionesProgramas.inversionTipos.inversionesTiposDetalles",
      'datosPersonaFisica.datosPersonales',
      'datosPersonasMorales',
      'datosPersonaFisica.negocios',
      'datosPersonaFisica.negocios.ciudades',
    ]);

    const defDoc= await this.generateDocDefinitionPdfMake(credito, showFirma)

    pdfMake.createPdf(defDoc).open();
  }

